n=int(input())
a=[list(map(int,input().split())) for _ in range(n)]
seen={0}
queue=[0]
while queue:
    u=queue.pop(0)
    for v in range(n):
        if a[u][v] and v not in seen:
            seen.add(v)
            queue.append(v)
print(len(seen))

